package net.minecraft.nbt;import java.util.*;public class NBTTagCompound{private final Map<String,Object> values=new HashMap<>();public void setBoolean(String k,boolean v){values.put(k,v);}public boolean getBoolean(String k){return Boolean.TRUE.equals(values.get(k));}public void setInteger(String k,int v){values.put(k,v);}public int getInteger(String k){return (int)values.getOrDefault(k,0);}}
